    const reason = 'QA-TEST סיבת מכירה';
    ctl = await prepare(context, newTitle('abroad-steps'));
    await createAbroadDraft(page, ctl, place);

    await page.getByRole('textbox', { name: 'סיבת מכירה' }).fill(reason);
    await page.getByRole('textbox', { name: 'מחזור שנתי' }).fill('500000');
    await page.getByRole('button', { name: NEXT }).click();
    await expect(page.getByRole('heading', { name: 'העלאת תמונות', exact: true }), 'шаг 3').toBeVisible(LOAD);
    await page.getByRole('button', { name: NEXT }).click();
    await expect(page.getByText(STEP4_HEADING).first(), 'шаг 4 (пакет не выбираем)').toBeVisible(LOAD);
    await expect
      .poll(() => ctl!.patches.length, { message: 'PATCH черновика на переходах 2→3 и 3→4', timeout: LOAD.timeout })
