    expect(meta?.overseas_location_details, 'сервер: место не потеряно после PATCH').toBe(place);

    await reopen(page, ctl);
    await expectAbroadDraft(page, place);
    await page.getByRole('button', { name: '2נתונים נוספים' }).click();
